import XCTest
@testable import CyberSkillDesign

final class ComponentLibraryTests: XCTestCase {
  func testExplicitThemeDensityAndContrastSelectDistinctModePacks() {
    let light = CSControlMode.pack(dark: false, highContrast: false, compact: false)
    let dark = CSControlMode.pack(dark: true, highContrast: false, compact: false)
    let compactHigh = CSControlMode.pack(dark: true, highContrast: true, compact: true)
    XCTAssertEqual(light.id, "light__default__comfortable__standard")
    XCTAssertEqual(dark.id, "dark__default__comfortable__standard")
    XCTAssertEqual(compactHigh.id, "dark__default__compact__high")
    XCTAssertNotEqual(light.componentButtonPrimaryBg.components, dark.componentButtonPrimaryBg.components)
    XCTAssertNotEqual(light.colorSemanticDanger.components, light.colorSemanticSuccess.components)
    XCTAssertEqual(light.radiusLg.points, 14)
    XCTAssertEqual(light.componentButtonMdMinHeight.points, 44)
    XCTAssertEqual(compactHigh.componentButtonMdPaddingX.points, 16)
  }

  func testFormAndFeedbackControlsKeepWebMeasurementRules() {
