  func testCatalogRulesMatchTheWebComponents() {
    XCTAssertEqual(CSPaginationModel.tokens(page: 2, count: 3), [.page(1), .page(2), .page(3)])
    XCTAssertEqual(CSPaginationModel.tokens(page: 1, count: 10), [.page(1), .page(2), .ellipsis, .page(10)])
    XCTAssertEqual(CSPaginationModel.tokens(page: 5, count: 10), [.page(1), .ellipsis, .page(4), .page(5), .page(6), .ellipsis, .page(10)])
    XCTAssertEqual(CSPaginationModel.tokens(page: 1, count: 0), [])
    XCTAssertEqual(CSNumberValue.clamp(-1, min: 0, max: 10), 0)
    XCTAssertEqual(CSNumberValue.clamp(11, min: 0, max: 10), 10)
    XCTAssertEqual(CSNumberValue.clamp(4, min: nil, max: nil), 4)
    XCTAssertEqual(CSRenderCount.whole(.nan, fallback: 5), 5)
    XCTAssertEqual(CSRenderCount.whole(4_294_967_296, fallback: 5), 5)
    XCTAssertEqual(CSRenderCount.whole(3.9, fallback: 5), 3)
    XCTAssertEqual(CSRenderCount.whole(-1.2, fallback: 5), 0)
    XCTAssertEqual(CSRatingValue.commit(current: 3, tapped: 3), 0)
    XCTAssertEqual(CSRatingValue.value(controlled: nil, inner: 2), 2)
    XCTAssertEqual(CSRatingValue.value(controlled: 0, inner: 2), 0)
    XCTAssertEqual(CSRatingValue.copy("label", language: nil), "Đánh giá")
    XCTAssertEqual(CSRatingValue.copy("label", language: "en"), "Rating")
    XCTAssertEqual(CSRatingValue.copy("label", language: "ja"), "Rating")
    XCTAssertEqual(CSRatingValue.groupName(label: nil, value: 3, max: 5, explicit: nil, hasLabelledBy: false, word: "Đánh giá"), "Đánh giá: 3 / 5")
    XCTAssertEqual(CSRatingValue.groupName(label: nil, value: 3, max: 5, explicit: nil, hasLabelledBy: false), "Rating: 3 / 5")
    XCTAssertEqual(CSRatingValue.groupName(label: "", value: 3, max: 5, explicit: nil, hasLabelledBy: false), ": 3 / 5")
    XCTAssertEqual(CSRatingValue.groupName(label: "Score", value: 3, max: 5, explicit: "", hasLabelledBy: false), "")
    XCTAssertNil(CSRatingValue.groupName(label: "Score", value: 3, max: 5, explicit: nil, hasLabelledBy: true))
    XCTAssertEqual(CSRatingValue.starLabel(index: 2, max: 5), "2 / 5")
    XCTAssertEqual(CSRatingValue.focusIndex(value: 0, max: 5), 0)
    XCTAssertEqual(CSRatingValue.focusIndex(value: 3, max: 5), 2)
    XCTAssertEqual(CSRatingValue.tabStop(index: 2, focus: 2, readOnly: false), 0)
    XCTAssertEqual(CSRatingValue.tabStop(index: 2, focus: 2, readOnly: true), -1)
    XCTAssertEqual(CSRatingValue.commit(current: 3, tapped: 4), 4)
    XCTAssertEqual(CSStepState.resolve(index: 0, current: 1), .done)
    XCTAssertEqual(CSStepState.resolve(index: 1, current: 1), .active)
    XCTAssertEqual(CSStepState.resolve(index: 2, current: 1), .todo)
    XCTAssertEqual(CSStepState.marker(state: .done, index: 2, number: 9), "✓")
    XCTAssertEqual(CSStepState.marker(state: .active, index: 0, number: 0), "0")
    XCTAssertEqual(CSStepState.marker(state: .todo, index: 3, number: nil), "4")
    XCTAssertTrue(CSStepState.isCurrent(.active))
    XCTAssertFalse(CSStepState.isCurrent(.done))
    XCTAssertFalse(CSStepState.isCurrent(.todo))
    XCTAssertEqual(CSStepState.copy("label", language: nil), "Các bước")
    XCTAssertEqual(CSStepState.copy("label", language: "en"), "Steps")
    XCTAssertEqual(CSStepState.copy("label", language: "ja"), "Steps")
    XCTAssertEqual(CSStepState.listName(explicit: "Custom", fallback: CSStepState.labelDefault), "Steps")
    XCTAssertEqual(CSStepState.listName(explicit: "", fallback: CSStepState.labelDefault), "Steps")
    XCTAssertEqual(CSStepState.currentValue(.active), "step")
    XCTAssertNil(CSStepState.currentValue(.todo))
    XCTAssertFalse(CSStepState.showsBody(nil))
    XCTAssertTrue(CSStepState.showsBody(""))
