    let a1 = CSTreeNode(key: "a1", label: "A1")
    let a2 = CSTreeNode(key: "a2", label: "A2", children: [CSTreeNode(key: "a2a", label: "A2a")])
    let a = CSTreeNode(key: "a", label: "A", children: [a1, a2])
    let nodes = [a, CSTreeNode(key: "b", label: "B")]
    XCTAssertEqual(CSTreeModel.visible(nodes: nodes, open: [:]).map(\.key), ["a", "b"])
    XCTAssertEqual(CSTreeModel.visible(nodes: nodes, open: ["a": true]).map(\.key), ["a", "a1", "a2", "b"])
    XCTAssertEqual(CSTreeModel.move(nodes: nodes, open: ["a": true], key: "a", arrow: .down), .focus("a1"))
    XCTAssertEqual(CSTreeModel.move(nodes: nodes, open: [:], key: "a", arrow: .right), .toggle("a"))
    XCTAssertEqual(CSTreeModel.move(nodes: nodes, open: ["a": true], key: "a", arrow: .right), .focus("a1"))
    XCTAssertEqual(CSTreeModel.move(nodes: nodes, open: ["a": true], key: "a", arrow: .left), .toggle("a"))
    XCTAssertEqual(CSTreeModel.move(nodes: nodes, open: ["a": true], key: "a1", arrow: .left), .focus("a"))
    XCTAssertNil(CSTreeModel.move(nodes: nodes, open: [:], key: "b", arrow: .down))
    XCTAssertEqual(CSTreeModel.openSiblings(nodes: nodes, key: "a1"), ["a2"])
    XCTAssertEqual(CSTreeModel.seedOpen(nodes: nodes, defaultOpen: true), ["a": true, "a2": true])
    XCTAssertEqual(CSTreeModel.findNode(nodes: nodes, key: "a2a")?.label, "A2a")
    XCTAssertEqual(CSTreeModel.initialFocusKey(nodes: nodes, selected: "a1"), "a1")
    XCTAssertEqual(CSTreeModel.initialFocusKey(nodes: nodes, selected: nil), "a")
    XCTAssertEqual(CSTreeModel.depth(nodes: nodes, key: "a2a"), 2)
    XCTAssertEqual(CSTreeModel.needle(previousText: "a", char: "A", elapsedMs: 100), "a")
    XCTAssertEqual(CSTreeModel.typeahead(nodes: nodes, open: ["a": true], currentKey: "a", needle: "a2"), "a2")
