  func testSwitchAndDialogExposeTheModeResolvedControls() {
    let dialog = CSDialog(title: "Notice", message: "Saved", confirmTitle: "OK", dark: false, highContrast: false, compact: false, onConfirm: {})
    XCTAssertEqual(dialog.title, "Notice")
    XCTAssertEqual(dialog.confirmTitle, "OK")
    XCTAssertEqual(CSDialogModel.describedBy(explicit: nil, hasExplicit: false, hasBody: true, bodyId: "d-body"), "d-body")
    XCTAssertNil(CSDialogModel.describedBy(explicit: nil, hasExplicit: false, hasBody: false, bodyId: "d-body"))
    XCTAssertNil(CSDialogModel.describedBy(explicit: "", hasExplicit: true, hasBody: true, bodyId: "d-body"))
    XCTAssertEqual(CSDialogModel.describedBy(explicit: "note", hasExplicit: true, hasBody: true, bodyId: "d-body"), "note")
    XCTAssertEqual(CSDialogModel.describedBy(explicit: " ", hasExplicit: true, hasBody: false, bodyId: "d-body"), " ")
    XCTAssertEqual(CSDialogModel.copy("close", language: nil), "Đóng")
    XCTAssertEqual(CSDialogModel.copy("close", language: "en"), "Close")
    XCTAssertEqual(CSDialogModel.copy("close", language: "ja"), "閉じる")
    XCTAssertEqual(CSDialogModel.copy("cancel", language: "japanese"), "キャンセル")
    XCTAssertEqual(CSDialogModel.closeText(nil, fallback: CSDialogModel.closeDefault), "Close")
    XCTAssertEqual(CSDialogModel.closeText("", fallback: CSDialogModel.closeDefault), "")
    XCTAssertFalse(CSDialogModel.showsClose(hasOpenChange: false, hasClose: false))
    XCTAssertFalse(CSDialogModel.showsActions(""))
    XCTAssertTrue(CSDialogModel.showsActions("0"))
    XCTAssertEqual(CSDialogModel.notify(hasOpenChange: true, hasClose: true), ["open-false", "close"])
    XCTAssertEqual(CSDialogModel.maxWidth(), 672)
  }
}
